={{
`You are an AI sales assistant for a digital services business.

Analyse the following customer enquiry.

Customer name: ${$('Edit Fields: Extract Customer Details').item.json.name}
Email: ${$('Edit Fields: Extract Customer Details').item.json.email}
Requested service: ${$('Edit Fields: Extract Customer Details').item.json.service}
Budget: $${$('Edit Fields: Extract Customer Details').item.json.budget}
Customer message: ${$('Edit Fields: Extract Customer Details').item.json.message}

Your task:
1. Assign a priority: high, medium, or low.
2. Categorise the requested service.
3. Summarise the enquiry in one sentence.
4. Recommend the next action for the sales team.

Priority guidelines:
- High: Budget of $10,000 or more.
- Medium: Budget between $3,000 and $9,999.
- Low: Budget below $3,000.

Return ONLY valid JSON using this structure:

{
  "priority": "high",
  "category": "Website Development",
  "summary": "Customer needs a new website.",
  "recommended_action": "Contact customer within 24 hours."
}

Do not include markdown formatting or additional explanations.`
}}

parameters.jsCode:
// Find Claude's text response
const textBlock = $json.content.find(
  block => block.type === 'text' && typeof block.text === 'string'
);

if (!textBlock) {
  throw new Error("No text response found from Claude");
}

// Parse the JSON
const analysis = JSON.parse(textBlock.text);

// Validate the response structure
if (!analysis || typeof analysis !== 'object' || Array.isArray(analysis)) {
  throw new Error("AI response must be a JSON object");
}

// Validate priority
const priority = typeof analysis.priority === 'string'
  ? analysis.priority.trim().toLowerCase()
  : '';

const validPriorities = ['high', 'medium', 'low'];

if (!validPriorities.includes(priority)) {
  throw new Error("Invalid AI priority: " + analysis.priority);
}

// Validate required fields
const requiredFields = [
  'category',
  'summary',
  'recommended_action'
];

for (const field of requiredFields) {
  if (
    typeof analysis[field] !== 'string' ||
    analysis[field].trim() === ''
  ) {
    throw new Error("Missing or invalid AI field: " + field);
  }
}

// Return validated analysis
return {
  json: {
    priority: priority,
    category: analysis.category,
    summary: analysis.summary,
    recommended_action: analysis.recommended_action
  }
};

